// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["EMAIL_CONFIG.statement_notify_to", "EMAIL_CONFIG.exception_notify_to"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

// Daily AP report: every email read the previous day, with each document it carried and what happened to it.
const rows = $input.all().map(i => i.json).filter(r => r && (r.id !== undefined || r.message_id || r.document_id));
const reportDate = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const txt = v => String(v ?? '').trim();
const money = v => { const n = Number(String(v ?? '').replace(/,/g, '')); return txt(v) !== '' && Number.isFinite(n) ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD' }) : ''; };

// One outcome per document: POSTED, SKIPPED (not a billing document / nothing to read), EXCEPTION, or OPEN (did not finish).
function outcome(r) {
  const status = txt(r.processing_status).toUpperCase();
  const reason = txt(r.exception_reason);
  const bill = txt(r.sage_bill_id);
  if (status === 'POSTED' && bill) return { kind: 'POSTED', text: `Posted to Sage, Bill ID ${bill}` };
  if (status === 'SKIPPED') return { kind: 'SKIPPED', text: `Skipped. ${reason.replace(/^[A-Z_]+:\s*/, '')}`.trim() };
  if (/^NOT_A_VALID_PDF/.test(reason)) return { kind: 'SKIPPED', text: `Skipped. ${reason.replace(/^[A-Z_]+:\s*/, '')}` };
  if (status === 'RECONCILED') return { kind: 'POSTED', text: 'Statement reconciled' };
  if (status === 'DUPLICATE') return { kind: 'EXCEPTION', text: `Duplicate. ${reason.replace(/^DUPLICATE:\s*/, '')}`.trim() };
  if (reason) return { kind: 'EXCEPTION', text: reason };
  if (status === 'POSTED') return { kind: 'EXCEPTION', text: 'Marked posted but no Sage Bill ID recorded' };
  return { kind: 'OPEN', text: status ? `Not completed (${status})` : 'Not completed' };
}

// Informational notes: price and quantity variances are reported, never enforced; location discrepancies are logged.
function notes(r) {
  const out = [];
  const v = Number(r.variance_amount);
  if (txt(r.variance_amount) !== '' && Number.isFinite(v) && Math.abs(v) >= 0.005) out.push(`Price variance vs PO: ${v > 0 ? '+' : '-'}${money(Math.abs(v))}`);
  const qty = /quantity: \w+ \(Not enforced\. ([^|)]+)\)/.exec(txt(r.match_details));
  if (qty) out.push(`Quantity variance: ${qty[1].trim()}`);
  const how = txt(r.location_method);
  if (/sources differ/i.test(how)) out.push('Ship To differs from PO location; PO used');
  if (/no location code in PO/i.test(how)) out.push('No location code in PO; Ship To used');
  if (/PO completed from the document text/i.test(txt(r.warnings))) out.push('PO number completed from the document text');
  return out;
}

const docs = rows.map(r => ({ r, o: outcome(r), n: notes(r) }));
const emails = [];
const byMsg = new Map();
for (const d of docs) {
  const key = txt(d.r.message_id) || `row-${d.r.id}`;
  if (!byMsg.has(key)) { const g = { subject: txt(d.r.subject) || '(no subject)', docs: [] }; byMsg.set(key, g); emails.push(g); }
  byMsg.get(key).docs.push(d);
}
const count = k => docs.filter(d => d.o.kind === k).length;
const totals = { emails: emails.length, documents: docs.length, posted: count('POSTED'), exceptions: count('EXCEPTION'), skipped: count('SKIPPED'), open: count('OPEN') };
const postedAmount = docs.filter(d => d.o.kind === 'POSTED').reduce((s, d) => s + (Number(String(d.r.total_amount ?? '').replace(/,/g, '')) || 0), 0);

const C = { primary: '#374151', accent: '#462CED', text: '#111827', line: '#E5E7EB', soft: '#F9FAFB' };
const COLOR = { POSTED: '#047857', EXCEPTION: '#B91C1C', SKIPPED: C.primary, OPEN: '#B45309' };
const th = `padding:8px;text-align:left;background:${C.primary};color:#FFFFFF;font-weight:bold;font-size:12px`;
const td = `padding:8px;border-bottom:1px solid ${C.line};vertical-align:top;font-size:13px`;
const HEAD = ['Document', 'Vendor', 'Invoice #', 'PO', 'Location', 'Amount', 'Outcome', 'Notes'];

const metric = (label, value) => `<td style="padding:10px 14px;border:1px solid ${C.line};text-align:center"><div style="font-size:22px;font-weight:bold;color:${C.accent}">${esc(value)}</div><div style="font-size:12px;color:${C.primary}">${esc(label)}</div></td>`;
const summary = `<table cellspacing="0" style="border-collapse:collapse;margin:0 0 20px"><tr>` +
  metric('Emails read', totals.emails) + metric('Documents', totals.documents) + metric('Posted to Sage', totals.posted) +
  metric('Exceptions', totals.exceptions) + metric('Skipped', totals.skipped) + (totals.open ? metric('Not completed', totals.open) : '') +
  metric('Amount posted', money(postedAmount) || '$0.00') + `</tr></table>`;

const body = emails.map((g, i) =>
  `<tr><td colspan="${HEAD.length}" style="padding:8px;background:${C.soft};border-top:2px solid ${C.primary};border-bottom:1px solid ${C.line};font-weight:bold;color:${C.text}">` +
  `${i + 1}. ${esc(g.subject)} <span style="font-weight:normal;color:${C.primary}">(${g.docs.length} document${g.docs.length === 1 ? '' : 's'})</span></td></tr>` +
  g.docs.map(({ r, o, n }) => {
    const loc = [txt(r.location_name), txt(r.location_method)].filter(Boolean);
    return `<tr>` +
      `<td style="${td}">${esc(txt(r.attachment_name) || (txt(r.document_type) === 'NO_INVOICE_CONTENT' ? 'Email body' : '(email body)'))}</td>` +
      `<td style="${td}">${esc(r.vendor_name)}</td>` +
      `<td style="${td}">${esc(r.invoice_number)}</td>` +
      `<td style="${td}">${esc(r.po_number)}</td>` +
      `<td style="${td}">${esc(loc[0] ?? '')}${loc[1] ? `<div style="font-size:11px;color:${C.primary}">${esc(loc[1])}</div>` : ''}</td>` +
      `<td style="${td};text-align:right;white-space:nowrap">${esc(money(r.total_amount))}</td>` +
      `<td style="${td};color:${COLOR[o.kind]};font-weight:bold">${esc(o.text)}</td>` +
      `<td style="${td}">${n.map(esc).join('<br>')}</td>` +
      `</tr>`;
  }).join('')
).join('');

const html =
  `<div style="font-family:Lato,Arial,sans-serif;color:${C.text};background:#FFFFFF;max-width:1100px">` +
  `<h2 style="color:${C.accent};margin:0 0 4px">AP Processing Report</h2>` +
  `<p style="margin:0 0 16px;color:${C.primary}">Emails read on ${esc(reportDate)}</p>` +
  summary +
  `<table cellspacing="0" style="border-collapse:collapse;width:100%">` +
  `<tr>${HEAD.map(h => `<th style="${th}">${h}</th>`).join('')}</tr>` +
  (body || `<tr><td colspan="${HEAD.length}" style="${td}">No emails were read on ${esc(reportDate)}.</td></tr>`) +
  `</table>` +
  `<p style="font-size:12px;color:${C.primary};margin:16px 0 0">Price and quantity variances are shown for information and do not stop posting. ` +
  `Exception emails stay unread in the AP inbox.</p>` +
  `</div>`;

return [{ json: { report_date: reportDate, ...totals, amount_posted: Math.round(postedAmount * 100) / 100, subject: `AP Processing Report for ${reportDate}`, html } }];
